window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2a343daf1fb2e2b"]={"versions": [{"id": "FIG-f2a343daf1fb2e2b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>CallbackDCMRequestServices</code>:</strong> Port/Interface für Benachrichtigungen über Diagnoseaktivitäten an SW-Cs.</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><strong><code>PduR</code> (PDU Router):</strong></li>\n<li><code>Dcm_PduR</code>: <code>«realize»</code> durch Dcm (TP-Pufferbereitstellung und Indikationen: <code>Dcm_StartOfReception</code>, <code>Dcm_CopyRxData</code>, <code>Dcm_TpRxIndication</code>, <code>Dcm_CopyTxData</code>, <code>Dcm_TpTxConfirmation</code>).</li>\n<li><code>PduR_General</code>: <code>«realize»</code> durch PduR (Triggerung diagnostischer Übertragungen via <code>PduR_DcmTransmit</code>).</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-fe47368c0d3e942e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>CallbackDCMRequestServices</code>:</strong> Port/Interface für Benachrichtigungen über Diagnoseaktivitäten an SW-Cs.</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><strong><code>PduR</code> (PDU Router):</strong></li>\n<li><code>Dcm_PduR</code>: <code>«realize»</code> durch Dcm (TP-Pufferbereitstellung und Indikationen: <code>Dcm_StartOfReception</code>, <code>Dcm_CopyRxData</code>, <code>Dcm_TpRxIndication</code>, <code>Dcm_CopyTxData</code>, <code>Dcm_TpTxConfirmation</code>).</li>\n<li><code>PduR_General</code>: <code>«realize»</code> durch PduR (Triggerung diagnostischer Übertragungen via <code>PduR_DcmTransmit</code>).</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-87852a3964f7beae", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>CallbackDCMRequestServices</code>:</strong> Port/Interface für Benachrichtigungen über Diagnoseaktivitäten an SW-Cs.</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><strong><code>PduR</code> (PDU Router):</strong></li>\n<li><code>Dcm_PduR</code>: <code>«realize»</code> durch Dcm (TP-Pufferbereitstellung und Indikationen: <code>Dcm_StartOfReception</code>, <code>Dcm_CopyRxData</code>, <code>Dcm_TpRxIndication</code>, <code>Dcm_CopyTxData</code>, <code>Dcm_TpTxConfirmation</code>).</li>\n<li><code>PduR_General</code>: <code>«realize»</code> durch PduR (Triggerung diagnostischer Übertragungen via <code>PduR_DcmTransmit</code>).</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-af412872e23bfc5e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>CallbackDCMRequestServices</code>:</strong> Port/Interface für Benachrichtigungen über Diagnoseaktivitäten an SW-Cs.</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><code>ComM_Types</code>: <code>«realize»</code> durch ComM.</li>\n<li><strong><code>PduR</code> (PDU Router):</strong> Als BSW-Modulkasten ohne explizit angebundene C-APIs / Schnittstellenkreise dargestellt.</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-fa046543ec00881c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><code>ComM_Types</code>: <code>«realize»</code> durch ComM.</li>\n<li><strong><code>PduR</code> (PDU Router):</strong> Modulblock ohne explizit angebundene C-APIs / Schnittstellenkreise.</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong><code>Csm</code> (Crypto Service Manager):</strong> <code>«optional»</code> vom Dcm referenziert für kryptografische Operationen.</li>\n<li><strong><code>KeyM</code> (Key Manager):</strong> <code>«optional»</code> vom Dcm referenziert für Schlüssel- und Zertifikatsmanagement.</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-4549d9ce28a82d13", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServicesCS</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs (Client-Server-Schnittstelle <code>DataServicesCS</code>).</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><code>ComM_Types</code>: <code>«realize»</code> durch ComM.</li>\n<li><strong><code>PduR</code> (PDU Router):</strong> Modulblock ohne explizit angebundene C-APIs / Schnittstellenkreise.</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong><code>Csm</code> (Crypto Service Manager):</strong> <code>«optional»</code> vom Dcm referenziert für kryptografische Operationen.</li>\n<li><strong><code>KeyM</code> (Key Manager):</strong> <code>«optional»</code> vom Dcm referenziert für Schlüssel- und Zertifikatsmanagement.</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}, {"id": "FIG-cd4e7d1039c0fc16", "releases": ["R22-11", "R23-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Komponenten- und Schnittstellendiagramm (UML-Komponentendiagramm mit Ports, Funktionsschnittstellen und Interface-Stereotypen).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Einbettung des <em>Diagnostic Communication Manager</em> (Dcm) in der AUTOSAR Classic Platform (R4.3.1) sowie Darstellung der statischen Abhängigkeiten zu Nachbarmodulen des BSW-Stacks (Dem, PduR, ComM, BswM, NvM, IoHwAb) und zur Applikationsebene (SW-Cs via RTE).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Dcm (Teil der <em>Communication Services</em> / <em>System Services</em>) fungiert als UDS- und OBD-Protokoll-Handler (ISO 14229-1, ISO 15031-5, SAE J1979). Er nimmt diagnostische PDUs entgegen, validiert Protokoll-/Sicherheitsbedingungen, steuert Sessions/Security-Level und delegiert Service-Payloads an interne Handler, BSW-Module oder SW-Cs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale BSW-Entität</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dcm</code>:</strong> Zentrales BSW-Modul, kapselt DSL (<em>Diagnostic Session Layer</em>), DSD (<em>Diagnostic Service Dispatcher</em>) und DSP (<em>Diagnostic Service Processing</em>).</li>\n</ul>\n<p class=\"fig-p\">#### Vertikale Interaktion zur Applikationsebene (via RTE)</p>\n<p class=\"fig-p\">Gekennzeichnet über den Container <em>„These are typically provided by SW-C's (through the RTE) (in certain cases also by other BSWMs)“</em> mittels Service-Ports und der Relation <code>«abswRequires»</code> (AUTOSAR BSW Requires Port):</p>\n<ul class=\"fig-list\">\n<li><strong><code>DataServices_DIDRange</code>:</strong> Port/Interface für dynamische oder bereichsbasierte DID-Abfragen (Read/Write DID Range).</li>\n<li><strong><code>DataServices</code> / <code>DataServicesPIDRPort</code>:</strong> Port/Interface zum Lesen/Schreiben diskreter DIDs bzw. OBD-PIDs.</li>\n<li><strong><code>SecurityAccess</code>:</strong> Port/Interface zur Seed/Key-Validierung und Security-Level-Freigabe (Service <code>0x27</code>).</li>\n<li><strong><code>InfotypeServices</code>:</strong> Port/Interface für OBD-Modus <code>$09</code> (Fahrzeug- und Kalibrier-Identifikationsdaten).</li>\n<li><strong><code>ServiceRequestNotification</code>:</strong></li>\n<li>Port <code>RequestManufacturerNotification</code> (OEM-spezifische Filterung/Validierung eingehender Requests).</li>\n<li>Port <code>ServiceRequestSupplierNotification</code> (Tier-1-spezifische Filterung/Validierung).</li>\n<li><strong><code>RoutineServices</code>:</strong> Port/Interface zur Routine-Steuerung (Start, Stop, Request Results; Service <code>0x31</code>).</li>\n<li><strong><code>CallbackDCMRequestServices</code>:</strong> Port/Interface für Benachrichtigungen über Diagnoseaktivitäten an SW-Cs.</li>\n<li><strong><code>RequestControlServices</code>:</strong> Port/Interface für OBD-Modus <code>$08</code> (On-Board System-/Aktuator-Steuerung).</li>\n</ul>\n<p class=\"fig-p\">#### Horizontale BSW-Schnittstellen (C-APIs mit Stereotypen <code>«realize»</code>, <code>«mandatory»</code>, <code>«optional»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ComM</code> (Communication Manager):</strong></li>\n<li><code>ComM_Dcm</code>: <code>«realize»</code> durch ComM, <code>«mandatory»</code> von Dcm benötigt (Status der Netzwerkkommunikation, Kanalaktivierung).</li>\n<li><code>Dcm_ComM</code>: <code>«realize»</code> durch Dcm, <code>«mandatory»</code> von ComM aufgerufen (Mitteilung über aktive Diagnose-Sessions, Keep-Alive/Full-Communication-Requests).</li>\n<li><code>ComM_Types</code>: <code>«realize»</code> durch ComM.</li>\n<li><strong><code>PduR</code> (PDU Router):</strong> Als BSW-Modulkasten ohne explizit angebundene C-APIs / Schnittstellenkreise dargestellt.</li>\n<li><strong><code>Dem</code> (Diagnostic Event Manager):</strong></li>\n<li><code>Dem_DcmReadDataOfOBDFreezeFrame</code>: <code>«realize»</code> durch Dem, <code>«optional»</code> vom Dcm referenziert (Auslesen von Freeze-Frame-Daten für OBD-Modus <code>$02</code> bzw. UDS-Service <code>0x19</code>).</li>\n<li><strong><code>BswM</code> (Basic Software Mode Manager):</strong></li>\n<li><code>BswM_Dcm_ApplicationUpdated</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> vom Dcm getriggert (z. B. nach Flash-/Reset-Zyklen).</li>\n<li><code>BswM_Dcm_CommunicationMode_CurrentState</code>: <code>«realize»</code> durch BswM, <code>«optional»</code> (Rückmeldung über aktuelle Diagnostic-Session/Communication-States zur Modus-Steuerung).</li>\n<li><strong><code>IoHwAb</code> (I/O Hardware Abstraction):</strong></li>\n<li><code>IoHwAb_Dcm</code>: <code>«realize»</code> durch IoHwAb, <code>«optional»</code> vom Dcm genutzt für Input/Output-Control (Service <code>0x2F</code>, Bypass der RTE für Low-Level-Hardware-Pins).</li>\n<li><strong><code>NvM</code> (Non-Volatile Memory Manager):</strong></li>\n<li><code>NvM_WriteBlock</code>: <code>«realize»</code> durch NvM, <code>«optional»</code> vom Dcm genutzt für direktes Schreiben nicht-flüchtiger Daten (z. B. Konfigurations- oder Kalibrierungs-DIDs).</li>\n<li><strong>Lifecycle & Schedule (SchM / EcuM):</strong></li>\n<li><code>Dcm_Init</code>: <code>«realize»</code> durch Dcm (Initialisierungs-API, aufgerufen durch EcuM/BswM).</li>\n<li><code>Dcm_MainFunction</code>: <code>«realize»</code> durch Dcm (Zyklischer BSW-Task, aufgerufen durch SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang & Puffer-Allokation (Asynchron, TP-Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein diagnostischer Frame trifft via Bus am Interface-Treiber ein und wird vom <code>PduR</code> an den Dcm gemeldet (<code>Dcm_StartOfReception</code> auf <code>Dcm_PduR</code>).</li>\n<li>Dcm allokiert den linearen Diagnosepuffer via DSL. Streaming der TP-Payloads über <code>Dcm_CopyRxData</code>.</li>\n<li>Abschluss des Empfangs via <code>Dcm_TpRxIndication</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Zustandskontrolle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm synchronisiert den Aktivitätsstatus mit <code>ComM</code> (<code>Dcm_ComM</code>), um Sleep-Modi während Diagnose-Sessions zu sperren (<code>COMM_FULL_COMMUNICATION</code>).</li>\n<li>Validierung via <code>RequestManufacturerNotification</code> / <code>RequestSupplierNotification</code> (Synchroner Rückgabewert <code>E_OK</code> oder NRC-Injection).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service-Dispatching & Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>DSD dekodiert SID/Subfunktion/DID und routet an DSP:</li>\n<li><strong>SW-C Dispatch:</strong> Asynchroner Aufruf über RTE-Client-Server-Ports (<code>DataServices</code>, <code>RoutineServices</code>, <code>SecurityAccess</code>). Rückgabe von <code>RTE_E_OK</code> oder <code>DCM_E_PENDING</code>.</li>\n<li><strong>BSW Dispatch:</strong> Synchrone/Asynchrone C-API-Aufrufe an <code>Dem</code> (FreezeFrames), <code>NvM</code> (NVM-Write) oder <code>IoHwAb</code> (Direct IO Control).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Task-Abarbeitung (<code>Dcm_MainFunction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung von Timeouts ($P2_{Server}$, $P2^*_{Server}$), Response-Pending-Handling (<code>NRC 0x78</code>) bei asynchronen Operationen (<code>DCM_E_PENDING</code>) sowie Routine-State-Monitoring.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Übertragung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Dcm initiiert Senden via <code>PduR_DcmTransmit</code> (<code>PduR_General</code>).</li>\n<li>Payload-Bereitstellung via <code>Dcm_CopyTxData</code>, Bestätigung über <code>Dcm_TpTxConfirmation</code>.</li>\n<li>Eventuelle Modus-Updates via <code>BswM_Dcm_CommunicationMode_CurrentState</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Kopplungs- und Konfigurationspflicht (<code>mandatory</code> vs. <code>optional</code>):</strong></li>\n<li>Die Schnittstellen zu <code>ComM</code> und <code>PduR</code> sind zwingend konfiguratorisch zu schließen; ohne aktives <code>ComM</code>-Channel-Mapping verbleibt der Dcm im Zustand <em>No Communication</em> und verwirft Requests.</li>\n<li><code>Dem</code>, <code>NvM</code>, <code>IoHwAb</code> und modusspezifische <code>BswM</code>-Ports sind bedingte Abhängigkeiten: Sie dürfen im BSW-Generator nur instanziiert und gelinkt werden, wenn korrespondierende UDS/OBD-Services (z. B. <code>0x19</code>, <code>0x2E</code>, <code>0x2F</code>, OBD <code>$02</code>) aktiv im Dcm-Konfigurationsbaum (<code>DcmDsdService</code>) aktiviert sind.</li>\n<li><strong>RTE-Vertrag & Non-Blocking Design:</strong></li>\n<li>SW-C-Server-Runnables für <code>DataServices</code> und <code>RoutineServices</code> müssen zwingend reentrant und nicht-blockierend ausgelegt sein. Länger dauernde Operationen müssen über das Polling-Muster <code>DCM_E_PENDING</code> implementiert werden, um ein Einfrieren der <code>Dcm_MainFunction</code> und Verletzungen der $P2_{Server}$-Zeitschranken zu verhindern.</li>\n<li><strong>Bypass-Option für Low-Level IO (<code>IoHwAb</code> vs. RTE):</strong></li>\n<li>Für UDS Service <code>0x2F</code> erlaubt die Spezifikation die Wahl zwischen dem Weg über Service-Ports (RTE $\\rightarrow$ SW-C) oder den direkten C-Call auf <code>IoHwAb_Dcm</code>. Für zeitkritische Hardware-Tests im End-of-Line-Modus bietet die direkte <code>IoHwAb</code>-Kopplung minimale Latenz ohne RTE-Overhead.</li>\n</ul>"}], "trans": [{"from": "FIG-f2a343daf1fb2e2b", "to": "FIG-fe47368c0d3e942e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fe47368c0d3e942e", "to": "FIG-87852a3964f7beae", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>ComM</code>: Die von <code>ComM</code> realisierte Schnittstelle <code>ComM</code> wurde in <code>ComM_Types</code> umbenannt.</li>\n</ul>"}, {"from": "FIG-87852a3964f7beae", "to": "FIG-af412872e23bfc5e", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PduR</code>: Die Schnittstellen <code>Dcm_PduR</code> (Stereotyp <code>«realize»</code> durch <code>Dcm</code>) und <code>PduR_General</code> wurden aus dem Diagramm entfernt.</li>\n</ul>"}, {"from": "FIG-af412872e23bfc5e", "to": "FIG-cd4e7d1039c0fc16", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cd4e7d1039c0fc16", "to": "FIG-fa046543ec00881c", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Csm</code>: BSW-Modul <code>Csm</code> neu hinzugefügt mit Abhängigkeit <code>«optional»</code> vom <code>Dcm</code>.</li>\n<li><code>KeyM</code>: BSW-Modul <code>KeyM</code> neu hinzugefügt mit Abhängigkeit <code>«optional»</code> vom <code>Dcm</code>.</li>\n<li><code>CallbackDCMRequestServices</code>: Der Port am <code>Dcm</code> und die zugehörige SW-C-Schnittstelle <code>CallbackDCMRequestServices</code> wurden entfernt.</li>\n</ul>"}, {"from": "FIG-fa046543ec00881c", "to": "FIG-4549d9ce28a82d13", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DataServices</code>: Die Schnittstelle <code>DataServices</code> wurde durch die Client-Server-Schnittstelle <code>DataServicesCS</code> ersetzt.</li>\n</ul>"}]};
